export function buildObjectTypeContent(
	...elements: NonEmptyArray<
		| T.ExportStatement
		| T.PropertySignature
		| T.CallSignature
		| T.ConstructSignature
		| T.IndexSignature
		| T.MethodSignature
	>
): ReturnType<typeof _buildObjectTypeContent>;
export function buildObjectTypeContent(
	options: { separator?: ',' | ';'; delimiter?: Delimiter.Leading | Delimiter.Trailing | Delimiter.Both },
	...elements: NonEmptyArray<
		| T.ExportStatement
		| T.PropertySignature
		| T.CallSignature
		| T.ConstructSignature
		| T.IndexSignature
		| T.MethodSignature
	>
): ReturnType<typeof _buildObjectTypeContent>;
export function buildObjectTypeContent(
	...args: (
		| { separator?: ',' | ';'; delimiter?: Delimiter.Leading | Delimiter.Trailing | Delimiter.Both }
		| (
				| T.ExportStatement
				| T.PropertySignature
				| T.CallSignature
				| T.ConstructSignature
				| T.IndexSignature
				| T.MethodSignature
		  )
	)[]
) {
	const _optsFirst =
		typeof args[0] === 'object' &&
		args[0] !== null &&
		!Array.isArray(args[0]) &&
		!('$type' in (args[0] as object)) &&
		Object.keys(args[0] as object).every((k) => ['separator', 'delimiter'].includes(k));
	const options = (_optsFirst ? args[0] : {}) as {
		separator?: ',' | ';';
		delimiter?: Delimiter.Leading | Delimiter.Trailing | Delimiter.Both;
	};
	const elements = (_optsFirst ? args.slice(1) : args) as unknown as NonEmptyArray<
		| T.ExportStatement
		| T.PropertySignature
		| T.CallSignature
		| T.ConstructSignature
		| T.IndexSignature
		| T.MethodSignature
	>;
	return _buildObjectTypeContent(elements, options);
}
function _buildObjectTypeContent(
	elements: NonEmptyArray<
		| T.ExportStatement
		| T.PropertySignature
		| T.CallSignature
		| T.ConstructSignature
		| T.IndexSignature
		| T.MethodSignature
	>,
	options: { separator?: ',' | ';'; delimiter?: Delimiter.Leading | Delimiter.Trailing | Delimiter.Both }
): T.ObjectTypeContent.Built {
	_assertNonEmpty(elements, 'object_type_content.elements');
	const _content = elements;
	const _separator =
		options.separator === undefined
			? undefined
			: ({ ',': TSKindId.Comma, ';': TSKindId.Semi } as Record<string, number>)[options.separator];
	const _delimiter = options.delimiter ?? Delimiter.None;
	return withMethods(
		withAccessors(
			{
				$type: TSKindId.ObjectTypeContent as const,
				$source: 2 as const,
				$named: true as const,
				_content,
				_separator,
				_delimiter,
				$with: {
					contents: (
						...vs: NonEmptyArray<
							| T.ExportStatement
							| T.PropertySignature
							| T.CallSignature
							| T.ConstructSignature
							| T.IndexSignature
							| T.MethodSignature
						>
					) => buildObjectTypeContent(options, ...vs),
					separator: (v: ',' | ';') => buildObjectTypeContent({ ...options, separator: v }, ...elements),
					delimiter: (v?: Delimiter.Leading | Delimiter.Trailing | Delimiter.Both) =>
						buildObjectTypeContent({ ...options, delimiter: v }, ...elements)
				}
			},
			{
				contents: () => _content
			}
		),
		methodsEngine
	);
}

